static class LRUCache {
    // 哨兵 head 的右边是刚用过的，哨兵 tail 的左边是最久没用的。换题时改容量和键值类型即可。
    static class Node {
        int key, val;
        Node prev, next;
        Node(int k, int v) { key = k; val = v; }
    }

    private final int cap;
    private final java.util.Map<Integer, Node> map = new java.util.HashMap<>();
    private final Node head = new Node(0, 0);
    private final Node tail = new Node(0, 0);

    public LRUCache(int capacity) {
        cap = capacity; // LC 146 保证 capacity >= 1
        head.next = tail;
        tail.prev = head;
    }

    public int get(int key) {
        Node n = map.get(key);
        if (n == null) return -1;
        unlink(n);
        addAfterHead(n);
        return n.val;
    }

    public void put(int key, int value) {
        Node n = map.get(key);
        if (n != null) { // 已存在只改值并刷新位置，不能再走淘汰
            n.val = value;
            unlink(n);
            addAfterHead(n);
            return;
        }
        if (map.size() == cap) {
            Node eldest = tail.prev;
            unlink(eldest);
            map.remove(eldest.key);
        }
        Node born = new Node(key, value);
        map.put(key, born);
        addAfterHead(born);
    }

    private void unlink(Node n) {
        n.prev.next = n.next;
        n.next.prev = n.prev;
    }

    private void addAfterHead(Node n) {
        n.prev = head;
        n.next = head.next;
        head.next.prev = n;
        head.next = n;
    }
}

