static class LFUCache {
    static class Node {
        int key, val, freq;
        Node prev, next;
        Node(int k, int v) { key = k; val = v; freq = 1; }
    }

    // 每个频次一条链表：头侧是该频次里刚用过的，尾侧是该频次里最久没用的
    static class Bucket {
        Node head = new Node(0, 0);
        Node tail = new Node(0, 0);
        int size;
        Bucket() {
            head.next = tail;
            tail.prev = head;
        }
        void addFront(Node n) {
            n.prev = head;
            n.next = head.next;
            head.next.prev = n;
            head.next = n;
            size++;
        }
        void remove(Node n) {
            n.prev.next = n.next;
            n.next.prev = n.prev;
            size--;
        }
        Node removeLast() {
            Node n = tail.prev;
            remove(n);
            return n;
        }
    }

    private final int cap;
    private int minFreq;
    private final java.util.Map<Integer, Node> map = new java.util.HashMap<>();
    private final java.util.Map<Integer, Bucket> buckets = new java.util.HashMap<>();

    public LFUCache(int capacity) { cap = capacity; }

    public int get(int key) {
        Node n = map.get(key);
        if (n == null) return -1;
        bump(n);
        return n.val;
    }

    public void put(int key, int value) {
        if (cap == 0) return;
        Node n = map.get(key);
        if (n != null) {
            n.val = value;
            bump(n);
            return;
        }
        if (map.size() == cap) {
            Bucket least = buckets.get(minFreq);
            Node victim = least.removeLast();
            if (least.size == 0) buckets.remove(minFreq);
            map.remove(victim.key);
            // 下面新键以频率 1 插入，并把 minFreq 置回 1
        }
        Node born = new Node(key, value);
        map.put(key, born);
        bucket(1).addFront(born);
        minFreq = 1;
    }

    private void bump(Node n) {
        Bucket old = buckets.get(n.freq);
        old.remove(n);
        if (old.size == 0) {
            buckets.remove(n.freq);
            if (n.freq == minFreq) minFreq++;
        }
        n.freq++;
        bucket(n.freq).addFront(n);
    }

    private Bucket bucket(int f) {
        Bucket b = buckets.get(f);
        if (b == null) {
            b = new Bucket();
            buckets.put(f, b);
        }
        return b;
    }
}

