import java.util.*; // 提供 HashMap 与 Map

class LRUCache {
    // 结点保存 key：淘汰时要用它从 cache 里删对应项
    private static class Node {
        int key;
        int value;
        Node prev;
        Node next;

        Node(int key, int value) {
            this.key = key;
            this.value = value;
        }
    }

    private final int capacity;
    private final Map<Integer, Node> cache = new HashMap<>();
    private final Node head = new Node(0, 0); // 哨兵，后面紧挨最近使用的结点
    private final Node tail = new Node(0, 0); // 哨兵，前面紧挨最久未使用的结点

    public LRUCache(int capacity) {
        if (capacity < 0) throw new IllegalArgumentException("capacity");
        this.capacity = capacity;
        head.next = tail;
        tail.prev = head;
    }

    public int get(int key) {
        Node node = cache.get(key);
        if (node == null) return -1;

        // 访问过就要变成最近使用，否则淘汰顺序会错
        moveToFront(node);
        return node.value;
    }

    public void put(int key, int value) {
        if (cache.containsKey(key)) {
            Node node = cache.get(key);
            node.value = value;
            moveToFront(node);
            return;
        }

        Node node = new Node(key, value);
        cache.put(key, node);
        addFirst(node);

        // 先插入再看长度，超容量时 tail 前驱就是最久未使用项
        if (cache.size() > capacity) {
            Node lru = tail.prev;
            remove(lru);
            cache.remove(lru.key);
        }
    }

    private void moveToFront(Node node) {
        remove(node);
        addFirst(node);
    }

    // 插到 head 与原第一个真实结点之间
    private void addFirst(Node node) {
        node.next = head.next;
        node.prev = head;
        head.next.prev = node;
        head.next = node;
    }

    // 只改前后指针，任意位置都能 O(1) 摘下
    private void remove(Node node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }
}

import java.util.*;

class LFUCache {
    static class Node {
        int key;
        int value;
        int freq = 1;

        Node(int key, int value) {
            this.key = key;
            this.value = value;
        }
    }

    private final int capacity;
    private int minFreq = 0;
    private final Map<Integer, Node> nodes = new HashMap<>();
    // 同一频率用插入顺序表示从最久到最近
    private final Map<Integer, LinkedHashSet<Integer>> freqKeys = new HashMap<>();

    public LFUCache(int capacity) {
        this.capacity = capacity;
    }

    public int get(int key) {
        Node node = nodes.get(key);
        if (node == null) return -1;
        touch(node);
        return node.value;
    }

    public void put(int key, int value) {
        if (capacity == 0) return;

        if (nodes.containsKey(key)) {
            Node node = nodes.get(key);
            node.value = value;
            touch(node);
            return;
        }

        if (nodes.size() == capacity) {
            // 迭代器第一个是该最低频率里最久没被访问的键
            LinkedHashSet<Integer> keys = freqKeys.get(minFreq);
            int evictKey = keys.iterator().next();
            keys.remove(evictKey);
            nodes.remove(evictKey);
            if (keys.isEmpty()) freqKeys.remove(minFreq);
        }

        Node node = new Node(key, value);
        nodes.put(key, node);
        freqKeys.computeIfAbsent(1, f -> new LinkedHashSet<>()).add(key);
        minFreq = 1;
    }

    private void touch(Node node) {
        int oldFreq = node.freq;
        LinkedHashSet<Integer> oldKeys = freqKeys.get(oldFreq);
        oldKeys.remove(node.key);

        // 这一档被拿空且正是全局最低频，最低频才要加一
        if (oldKeys.isEmpty()) {
            freqKeys.remove(oldFreq);
            if (minFreq == oldFreq) minFreq++;
        }

        node.freq++;
        // 加到新频率集合末尾，表示该频率下最近使用
        freqKeys.computeIfAbsent(node.freq, f -> new LinkedHashSet<>()).add(node.key);
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class MinStack {
    // 每帧存 [当前值, 入栈后的最小值]，弹出后上一帧的最小值仍在。
    private final Deque<int[]> stack = new ArrayDeque<>();

    public MinStack() {
    }

    public void push(int val) {
        int currentMin = stack.isEmpty()
                ? val
                : Math.min(val, stack.peek()[1]);
        stack.push(new int[]{val, currentMin});
    }

    public void pop() {
        stack.pop();
    }

    public int top() {
        return stack.peek()[0];
    }

    public int getMin() {
        // 最小值已写在栈顶帧的第二项，不用再扫描。
        return stack.peek()[1];
    }
}

import java.util.*;

class MyStack {
    // 单队列模拟栈，栈顶始终保持在队首。
    private final Queue<Integer> queue = new ArrayDeque<>();

    public void push(int x) {
        int oldSize = queue.size();
        queue.offer(x);

        // 只旋转入队前的旧元素，让 x 留在队首。
        for (int i = 0; i < oldSize; i++) {
            queue.offer(queue.poll());
        }
    }

    public int pop() {
        return queue.remove(); // 队首即栈顶。
    }

    public int top() {
        return queue.element();
    }

    public boolean empty() {
        return queue.isEmpty();
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class MyQueue {
    private final Deque<Integer> inStack = new ArrayDeque<>();
    private final Deque<Integer> outStack = new ArrayDeque<>();

    public void push(int x) {
        // 入队只写 inStack，不碰出队栈
        inStack.push(x);
    }

    public int pop() {
        moveIfNeeded();
        return outStack.pop();
    }

    public int peek() {
        moveIfNeeded();
        return outStack.peek();
    }

    public boolean empty() {
        // 两边都空，队列里才没有元素
        return inStack.isEmpty() && outStack.isEmpty();
    }

     private void moveIfNeeded() {
         // 出队栈还有数就保持原顺序，避免重复倒
         if (outStack.isEmpty()) {
             while (!inStack.isEmpty()) {
                 // 再压一次把队首翻到 outStack 栈顶
                 outStack.push(inStack.pop());
             }
         }
     }
 }

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Trie {
    private static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        boolean isWord;
    }

    private final TrieNode root = new TrieNode();

    public Trie() {
    }

    public void insert(String word) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            int index = c - 'a';
            // 这条字母边还没有，就补一个节点再往下走
            if (node.children[index] == null) {
                node.children[index] = new TrieNode();
            }
            node = node.children[index];
        }
        // 路径只说明前缀在，isWord 才表示单词在这里结束
        node.isWord = true;
    }

    public boolean search(String word) {
        TrieNode node = find(word);
        // 必须走到末尾，并且该节点是单词结尾
        return node != null && node.isWord;
    }

    public boolean startsWith(String prefix) {
        return find(prefix) != null;
    }

    private TrieNode find(String text) {
        TrieNode node = root;
        for (char c : text.toCharArray()) {
            int index = c - 'a';
            if (node.children[index] == null) return null;
            node = node.children[index];
        }
        return node;
    }
}
